"use strict";(globalThis.webpackChunkgrc||=[]).push([[25390],{69819(e){e.exports=JSON.parse('{"citeKey":"sun2002paralleltwo","slug":"sun-2002-parallel-two-9081","title":"A Parallel Two-level Hybrid Method for Diagonal Dominant Tridiagonal Systems","authors":["X.-H. Sun","W. Zhang"],"venue":"The 2002 International Parallel and Distributed Processing Symposium (IPDPS 2002), Fort Lauderdale, FL","type":"Conference","entryType":"inproceedings","date":"April, 2002","year":2002,"era":"iit","month":4,"doi":"10.1109/ipdps.2002.1015573","abstract":"A new method, namely the Parallel Two-Level Hybrid (PTH) method, is developed to solve tridiagonal systems on parallel computers. PTH is designed based on Parallel Diagonal Dominant (PDD) algorithm. Like PDD, PTH is highly scalable. It provides accurate solutions when PDD may not be applicable and maintains a near PDD performance when the underlying machine ensemble size is large. By controlling its two-level partition, PTH can deliver optimal performance for different machine ensemble and problem sizes. Theoretical analyses and numerical experiments indicate that PTH is significantly better than existing methods for many scientific and engineering applications.","hasAbstract":true,"lede":"A new method, namely the Parallel Two-Level Hybrid (PTH) method, is developed to solve tridiagonal systems on parallel computers.","links":{"pdf":"https://grc.iit.edu/papers/2002/sun-2002-parallel-two-9081.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);